   $('#pbOptionSession').onchange=()=>movements().catch(e=>toast(e.message,'error'));await movements();$('#pbOptionForm').onsubmit=async e=>{e.preventDefault();if(state.preview)return toast('Preview only');const f=new FormData(e.target),chosen=[...host.querySelectorAll('[data-pb-keep]:checked')].map(b=>({id:b.dataset.pbKeep,sets:Number(host.querySelector(`[data-pb-sets="${b.dataset.pbKeep}"]`).value)}));if(!chosen.length)return toast('Keep at least one assigned movement');setBusy(e.submitter,true);try{await query('Approve workout option',db.from('playbook_workout_options').upsert({client_id:id,coach_id:state.user.id,session_id:f.get('session_id'),minutes:Number(f.get('minutes')),location:f.get('location'),energy:f.get('energy'),exercises:chosen,note:f.get('note'),approved:true},{onConflict:'session_id,minutes,location,energy'}).select().single());toast('Option approved');loadOptions();}catch(err){toast(err.message,'error');setBusy(e.submitter,false);}};
