 const legacyIndex=clearClientDestinations.findIndex(d=>d[0]==='learning');if(legacyIndex>=0)clearClientDestinations.splice(legacyIndex,1); // One Playbook entry in main navigation.
 const coachBefore=renderCoach;
 renderCoach=function(){if(!state.client&&['resources','playbook-manager'].includes(state.coachView)){state.coachView='playbook-manager';return manager();}const k=state.client?.id,result=coachBefore();Promise.resolve(result).then(async()=>{if(!k||state.client?.id!==k||$('#pbCoachTools'))return;const host=$('#clientWorkspaceBody')||managerHost();host.insertAdjacentHTML('beforeend',`<section class="pb-coach-tools" id="pbCoachTools"><h3>Playbook support</h3>${button('Recommend a guide','id="pbProfileRecommend"','ghost small')}${button('Approve workout options','id="pbProfileOptions"','ghost small')}<div id="pbClientChanges"></div></section>`);$('#pbProfileRecommend').onclick=()=>{managerClient=k;managerTab='recommendations';state.client=null;state.coachView='playbook-manager';renderCoach();};$('#pbProfileOptions').onclick=()=>{managerClient=k;managerTab='workout options';state.client=null;state.coachView='playbook-manager';renderCoach();};if(!state.preview){try{const h=await query('Client workout changes',db.from('playbook_workout_history').select('*').eq('client_id',k).order('created_at',{ascending:false}).limit(20));if(state.client?.id!==k||!$('#pbClientChanges'))return;$('#pbClientChanges').innerHTML=`<details><summary>Accepted workout changes (${h.length})</summary>${h.map(x=>`<article class="pb-meal"><p>${esc(new Date(x.created_at).toLocaleString())} · ${x.active?'Active option':'Original restored / superseded'}</p><p>${esc(x.note)}</p><ul>${x.adjusted.map(e=>`<li>${esc(e.name)} · ${e.sets} × ${esc(e.reps||'assigned reps')}</li>`).join('')}</ul><details><summary>Original prescription</summary><ul>${x.original.map(e=>`<li>${esc(e.name)} · ${e.sets} × ${esc(e.reps||'assigned reps')}</li>`).join('')}</ul></details></article>`).join('')||'<p>No accepted changes yet.</p>'}</details>`;}catch{if($('#pbClientChanges'))$('#pbClientChanges').textContent='Workout history could not load.';}}}).catch(()=>{});return result;};
 // Existing onboarding evidence/funding remain intact; the duplicate legacy content editor is retired.
 journeyCoachExtras=async function(host){const funding=host.querySelector('[name=funding_mode]');if(funding){const paint=()=>{const ref=host.querySelector('[name=funding_reference]');ref.closest('label').hidden=funding.value!=='corporate';ref.required=funding.value==='corporate';};funding.onchange=paint;paint();}host.insertAdjacentHTML('beforeend','<div id="journeyEvidence"></div>');};
 document.addEventListener('DOMContentLoaded',()=>{if(state.preview&&new URLSearchParams(location.search).get('tab')==='playbook'){state.clientView='playbook';renderClient();}const existing=$('#coachNav [data-coach-view="resources"]');if(existing){existing.dataset.coachView='playbook-manager';existing.innerHTML='<span aria-hidden="true">▤</span>Playbook Manager';existing.onclick=()=>{state.client=null;state.coachView='playbook-manager';renderCoach();};}updateClientNav();});
 const employerBefore=renderEmployerPortal;
 renderEmployerPortal=async function(){await employerBefore();const selector=$('#employerPilot');if(!selector||state.role!=='employer')return;$('#employerMain').insertAdjacentHTML('beforeend','<section class="panel" id="pbEmployerReport"><h2>Playbook participation</h2><div role="status" id="pbEmployerFigures">Loading anonymous group report…</div></section>');let request=0;async function refresh(){const v=++request,p=selector.value;try{const r=await query('Firm Playbook participation',db.rpc('playbook_firm_report',{p_pilot:p}));if(v===request&&state.role==='employer'&&selector.value===p&&$('#pbEmployerFigures'))$('#pbEmployerFigures').innerHTML=reportMarkup(r);}catch{if($('#pbEmployerFigures'))$('#pbEmployerFigures').textContent='Group participation report unavailable.';}}selector.addEventListener('change',refresh);await refresh();};
 window.LegalEdgePlaybook={open:(view='home')=>{if(owner!==key())reset();subview=view;route('playbook');},reportMarkup};
